                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="left"
                  dataKey="volumeIndex2025"
                  name="Volume index 2025"
                  fill={C.correspondent}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="outboundTouchPct"
                  name="Outbound touch %"
                  stroke={C.fps}
                  strokeWidth={2}
                />
              </ComposedChart>
            </ResponsiveContainer>
